INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('e512054c-240f-461d-9ccd-e6cc5c9e6411', 'advanced', 'multiple_choice', 'A yarn producer''s technical team compares ''air-covered'' spandex yarn (spandex wrapped with air-entangled filament, using compressed air to intermingle rather than true mechanical covering/wrapping as in SCY/DCY) against traditional mechanically-covered spandex. What SPEED/COST advantage does air-covering typically offer, and what is its main functional LIMITATION compared to true mechanical covering?', '["Air-covering and mechanical covering are functionally and economically identical processes, making any comparison between them technically meaningless","Air-covering can run at significantly HIGHER production speeds (no mechanical rotation/twisting hardware limiting throughput, similar in principle to the earlier interlacing/intermingling technique used on flat filament yarn) at lower cost, but generally provides LESS complete/durable coverage and protection of the spandex core than true mechanical wrapping (SCY/DCY), since air-entanglement creates a looser, less securely bound covering structure than physically wrapped/twisted covering","Air-covering always provides MORE complete and durable core protection than mechanical covering, the reverse of the actual typical relationship between these two covering methods","Air-covering can only be used on 100% cotton yarn with zero spandex content, making the entire premise of comparing it to spandex-covering methods technically inapplicable"]'::jsonb, 'Air-covering can run at significantly HIGHER production speeds (no mechanical rotation/twisting hardware limiting throughput, similar in principle to the earlier interlacing/intermingling technique used on flat filament yarn) at lower cost, but generally provides LESS complete/durable coverage and protection of the spandex core than true mechanical wrapping (SCY/DCY), since air-entanglement creates a looser, less securely bound covering structure than physically wrapped/twisted covering', 'This connects the earlier SCY/DCY-covered-yarn and air-jet-interlacing discussions into a genuine speed-vs-protection tradeoff — air-covering uses compressed air (similar underlying principle to flat-filament interlacing) to intermingle a covering yarn around the spandex core WITHOUT true mechanical rotation/wrapping, allowing much higher production speeds and lower cost than SCY/DCY''s mechanical winding process — but this speed advantage comes at the cost of LESS complete, less durable core protection/coverage, since air-entangled fiber isn''t as securely bound around the core as a true mechanically wrapped covering, making air-covering more suitable for less demanding applications while SCY/DCY remains preferred where maximum core protection/appearance consistency (like fine hosiery, as discussed earlier) is critical.', 3, '{"air-covered-vs-mechanical-covered-spandex"}'::text[]),
('e512054c-240f-461d-9ccd-e6cc5c9e6411', 'advanced', 'multiple_choice', 'A technical yarn lab measures ''loop tenacity'' (breaking strength of a yarn when formed into a small loop and pulled, rather than tested as a straight single strand) as a SEPARATE specification from standard straight-strand tenacity. Why does loop tenacity matter as an additional, distinct test for yarns intended for KNITTING applications specifically?', '["Loop tenacity and straight-strand tenacity always produce mathematically identical results for any yarn, making this separate test entirely redundant with zero additional information","Since knitting inherently forms the yarn into LOOPS (as established throughout the knitting domain discussion) rather than keeping it straight, the yarn experiences genuine LOOP-CONFIGURATION stress during both the knitting process itself and later fabric use (e.g., a snag catching one loop) — loop tenacity specifically tests strength under this more representative, curved/bent stress configuration, which can be measurably LOWER than straight-strand tenacity for some yarns (due to stress concentration at the bend), making it a more directly relevant specification for predicting real knitting-application performance than straight-strand tenacity alone","Loop tenacity is only relevant for woven fabric applications, never for knitting, making this described test''s connection to knitting yarn specification technically backwards","Loop configuration during testing has no relationship to how yarn actually behaves during knitting or in a finished knit fabric, making loop tenacity testing a purely theoretical exercise with zero practical relevance"]'::jsonb, 'Since knitting inherently forms the yarn into LOOPS (as established throughout the knitting domain discussion) rather than keeping it straight, the yarn experiences genuine LOOP-CONFIGURATION stress during both the knitting process itself and later fabric use (e.g., a snag catching one loop) — loop tenacity specifically tests strength under this more representative, curved/bent stress configuration, which can be measurably LOWER than straight-strand tenacity for some yarns (due to stress concentration at the bend), making it a more directly relevant specification for predicting real knitting-application performance than straight-strand tenacity alone', 'This connects the earlier tenacity/elongation discussion and the entire knitting-domain loop-structure emphasis into a specific, end-use-matched testing rationale — since a knit fabric''s yarn is PERMANENTLY held in a curved LOOP configuration (not straight), and can experience real-world stress in this same curved configuration (e.g., a snag catching and pulling on a single loop), loop tenacity testing (bending the yarn into a loop before testing breaking strength) more accurately represents the yarn''s real functional strength for KNITTING applications than straight-strand tenacity alone — some yarns show measurably lower loop tenacity than straight tenacity due to stress concentration at the bend point, making this a genuinely informative, end-use-matched supplementary specification, directly paralleling the earlier lesson about matching test METHOD to the actual application''s real stress conditions (like the earlier gauge-length and gray-scale test-method-matching discussions).', 3, '{"loop-tenacity-knitting-relevance"}'::text[]);
COMMIT;
